import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const b=JSON.parse('{"title":"Εισαγωγή και εξαγωγή πακέτων","description":"","frontmatter":{},"headers":[],"relativePath":"el/websites/portable-packages.md","filePath":"el/websites/portable-packages.md"}'),l={name:"el/websites/portable-packages.md"};function s(r,a,n,c,d,h){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="εισαγωγη-και-εξαγωγη-πακετων" tabindex="-1">Εισαγωγή και εξαγωγή πακέτων <a class="header-anchor" href="#εισαγωγη-και-εξαγωγη-πακετων" aria-label="Permalink to &quot;Εισαγωγή και εξαγωγή πακέτων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς — προσχέδιο βάσει κώδικα</p><p>TransferBook+ v0.7.9. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις. Ο οδηγός δεν επιβεβαιώνει δημόσια δημοσίευση.</p></div><h2 id="επιλογη-πακετου" tabindex="-1">Επιλογή πακέτου <a class="header-anchor" href="#επιλογη-πακετου" aria-label="Permalink to &quot;Επιλογή πακέτου&quot;">​</a></h2><ul><li><code>.tbsite.json</code>: δομή ιστοσελίδας πολλαπλών σελίδων μαζί με το σύστημα σχεδιασμού.</li><li><code>.tbtheme.json</code>: φορητό οπτικό πρότυπο, με συμβόλαιο αναφοράς v2.</li></ul><h2 id="ασφαλης-μεταφορα" tabindex="-1">Ασφαλής μεταφορά <a class="header-anchor" href="#ασφαλης-μεταφορα" aria-label="Permalink to &quot;Ασφαλής μεταφορά&quot;">​</a></h2><ol><li>Εξαγάγετε το αρχείο από το κατάλληλο εργαλείο. Κρατήστε ανέπαφο το αρχικό αρχείο ως αντίγραφο ανάκτησης.</li><li>Μεταφέρετε το αρχείο στον εξουσιοδοτημένο προορισμό με εγκεκριμένο τοπικό τρόπο.</li><li>Εισαγάγετε στο Website Studio για προσχέδιο ιστοσελίδας ή στο Template Manager για πρότυπο. Το Website Studio μπορεί επίσης να μετατρέψει συμβατό πρότυπο σε προσχέδιο πολλών σελίδων.</li><li>Ελέγξτε επικύρωση, σελίδες και συσκευές και αποθηκεύστε όπου υποστηρίζεται.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Τα εισαγόμενα πακέτα αντιμετωπίζονται ως προσχέδια. Τα checksums ανιχνεύουν τυχαία αλλοίωση, όχι αυθεντικότητα. Δεν εξουσιοδοτούν δημοσίευση.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Μην παρακάμπτετε σφάλματα ακεραιότητας. Εξαγάγετε ξανά από την πηγή και ελέγξτε συμβατότητα. Ο validator αναφοράς απορρίπτει blueprints άνω των 2 MB, μη ασφαλείς διαδρομές, μη εγκεκριμένα αρχεία, scripts και ασύμβατα schemas. Δείτε <a href="./publication-controls.html">ελέγχους δημοσίευσης</a>.</p><h2 id="επιλογες-εισαγωγης-στη-v0-7-10" tabindex="-1">Επιλογές εισαγωγής στη v0.7.10 <a class="header-anchor" href="#επιλογες-εισαγωγης-στη-v0-7-10" aria-label="Permalink to &quot;Επιλογές εισαγωγής στη v0.7.10&quot;">​</a></h2><p><strong>Κατάσταση: έκδοση staging ελεγμένη βάσει κώδικα.</strong> Το Website Studio διακρίνει τα πακέτα ιστοσελίδας, τα πακέτα προτύπων και τα πλήρη αντίγραφα JSON χώρου εργασίας.</p><p>Κατά την εισαγωγή προτύπου επιλέξτε εφαρμογή των tokens στην τρέχουσα ιστοσελίδα ή εισαγωγή νέας ιστοσελίδας πολλών σελίδων. Ελέγξτε τον στόχο: η εφαρμογή tokens αλλάζει τον σχεδιασμό της συγκεκριμένης ιστοσελίδας, ενώ η νέα ιστοσελίδα είναι χωριστό προσχέδιο. Επικυρώστε το πακέτο, ελέγξτε το αποτέλεσμα ανά γλώσσα και συσκευή και αποθηκεύστε. Κρατήστε αντίγραφο πριν από την αλλαγή.</p><p>Χρησιμοποιήστε πλήρες αντίγραφο χώρου εργασίας μόνο στην αντίστοιχη διαδικασία ανάκτησης, όχι αντί φορητού πακέτου σχεδιασμού. Ισχύουν τα όρια εταιρείας και τρόπου λειτουργίας.</p>',14)])])}const u=e(l,[["render",s]]);export{b as __pageData,u as default};
